import { useState } from 'react';
import { Link, NavLink } from 'react-router';
import { ArrowUpRight, ChevronDown, Menu, X } from 'lucide-react';
import { services } from '@/data/site';
export function SiteHeader(){const [open,setOpen]=useState(false);const [mega,setMega]=useState(false);return <header className="site-header"><Link to="/" className="wordmark" onClick={()=>setOpen(false)}><span className="logo-mark">m</span><span>MINDTEL<small>SOLUTIONS</small></span></Link><nav className={open?'main-nav mobile-open':'main-nav'} aria-label="Main navigation">{['Home','About','Services','Industries','Work','Insights','Careers','Contact'].map(n=>n==='Services'?<div className="services-nav" key={n} onMouseEnter={()=>setMega(true)} onMouseLeave={()=>setMega(false)}><div className="service-nav-label"><NavLink to="/services" onClick={()=>setOpen(false)}>Services</NavLink><button aria-label="Show services" aria-expanded={mega} onClick={()=>setMega(!mega)}><ChevronDown size={12}/></button></div>{mega&&<div className="mega-menu"><div><span className="eyebrow">OUR CAPABILITIES</span><h3>Connected expertise.<br/>Useful outcomes.</h3><Link to="/services" onClick={()=>{setMega(false);setOpen(false)}}>Explore all services <ArrowUpRight size={16}/></Link></div><div className="mega-links">{services.map((s,i)=><Link key={s.slug} to={'/services/'+s.slug} onClick={()=>{setMega(false);setOpen(false)}}><small>{String(i+1).padStart(2,'0')}</small>{s.name}<ArrowUpRight size={14}/></Link>)}</div></div>}</div>:<NavLink key={n} to={n==='Home'?'/':'/'+n.toLowerCase()} onClick={()=>setOpen(false)}>{n}</NavLink>)}</nav><Link className="header-cta" to="/contact">Let’s Talk <ArrowUpRight size={15}/></Link><button className="mobile-toggle" onClick={()=>setOpen(!open)} aria-label={open?'Close navigation':'Open navigation'}>{open?<X/>:<Menu/>}</button></header>}
